PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER DEFAULT 0 NOT NULL, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY NOT NULL, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE TABLE account (id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE verification (id TEXT PRIMARY KEY NOT NULL, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE passkey (id TEXT PRIMARY KEY NOT NULL, name TEXT, public_key TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, credential_id TEXT NOT NULL UNIQUE, counter INTEGER NOT NULL, device_type TEXT NOT NULL, backed_up INTEGER NOT NULL, transports TEXT, created_at INTEGER NOT NULL, aaguid TEXT);
CREATE TABLE project (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE project_member (project_id TEXT NOT NULL REFERENCES project(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','member')), joined_at INTEGER NOT NULL, PRIMARY KEY(project_id,user_id));
CREATE TABLE project_invitation (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES project(id) ON DELETE CASCADE, invited_user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, role TEXT DEFAULT 'member' NOT NULL, status TEXT DEFAULT 'pending' NOT NULL CHECK(status IN ('pending','accepted','revoked','expired')), invited_by TEXT NOT NULL REFERENCES user(id), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX invitation_project_user_status_idx ON project_invitation(project_id,invited_user_id,status);
CREATE TABLE item (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES project(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL, manufacturer TEXT, model_number TEXT, price_yen INTEGER NOT NULL CHECK(price_yen >= 0), amortization_start_month TEXT NOT NULL, useful_life_months INTEGER NOT NULL CHECK(useful_life_months >= 1), note TEXT, created_by TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX item_project_id_idx ON item(project_id,id);
